<span class="line">  <span class="token comment">// 消息提示</span></span>
<span class="line">  <span class="token function-variable function">showToast</span><span class="token operator">:</span> <span class="token punctuation">(</span>options<span class="token operator">:</span> <span class="token builtin">any</span><span class="token punctuation">)</span> <span class="token operator">=></span> wx<span class="token punctuation">.</span><span class="token function">showToast</span><span class="token punctuation">(</span>options<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
