<span class="line"></span>
<span class="line"><span class="token comment">// 2. 定义请求适配器</span></span>
<span class="line"><span class="token keyword">const</span> requestAdapter <span class="token operator">=</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token function-variable function">request</span><span class="token operator">:</span> <span class="token punctuation">(</span>config<span class="token operator">:</span> <span class="token builtin">any</span><span class="token punctuation">)</span> <span class="token operator">=></span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token keyword">new</span> <span class="token class-name"><span class="token builtin">Promise</span></span><span class="token punctuation">(</span><span class="token punctuation">(</span>resolve<span class="token punctuation">,</span> reject<span class="token punctuation">)</span> <span class="token operator">=></span> <span class="token punctuation">{</span></span>
<span class="line">      wx<span class="token punctuation">.</span><span class="token function">request</span><span class="token punctuation">(</span><span class="token punctuation">{</span></span>
<span class="line">        url<span class="token operator">:</span> config<span class="token punctuation">.</span>url<span class="token punctuation">,</span></span>
<span class="line">        method<span class="token operator">:</span> config<span class="token punctuation">.</span>method <span class="token operator">||</span> <span class="token string">'GET'</span><span class="token punctuation">,</span></span>
<span class="line">        data<span class="token operator">:</span> config<span class="token punctuation">.</span>data<span class="token punctuation">,</span></span>
<span class="line">        header<span class="token operator">:</span> config<span class="token punctuation">.</span>headers<span class="token punctuation">,</span></span>
<span class="line">        timeout<span class="token operator">:</span> config<span class="token punctuation">.</span>timeout<span class="token punctuation">,</span></span>
<span class="line">        <span class="token function-variable function">success</span><span class="token operator">:</span> <span class="token punctuation">(</span>res<span class="token punctuation">)</span> <span class="token operator">=></span> <span class="token punctuation">{</span></span>
<span class="line">          appLog<span class="token punctuation">.</span><span class="token function">debug</span><span class="token punctuation">(</span><span class="token string">'Request successful'</span><span class="token punctuation">,</span> <span class="token punctuation">{</span></span>
<span class="line">            url<span class="token operator">:</span> config<span class="token punctuation">.</span>url<span class="token punctuation">,</span></span>
<span class="line">            statusCode<span class="token operator">:</span> res<span class="token punctuation">.</span>statusCode<span class="token punctuation">,</span></span>
<span class="line">            duration<span class="token operator">:</span> res<span class="token punctuation">.</span>profile<span class="token operator">?.</span>sslConnectionTime</span>
<span class="line">          <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
