<span class="line">  <span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  </span>
<span class="line">  <span class="token keyword">const</span> kit<span class="token operator">:</span> IKit <span class="token operator">=</span> <span class="token punctuation">{</span></span>
<span class="line">    platformBridge<span class="token punctuation">,</span></span>
<span class="line">    storeEngine<span class="token punctuation">,</span></span>
<span class="line">    request<span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">      baseUrl<span class="token operator">:</span> process<span class="token punctuation">.</span>env<span class="token punctuation">.</span><span class="token constant">API_BASE_URL</span> <span class="token operator">||</span> <span class="token string">'https://api.shop.example.com'</span><span class="token punctuation">,</span></span>
<span class="line">      adapter<span class="token operator">:</span> requestAdapter<span class="token punctuation">,</span></span>
