<span class="line">        <span class="token string-property property">'X-App-Version'</span><span class="token operator">:</span> <span class="token string">'1.0.0'</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token string-property property">'X-Client-Type'</span><span class="token operator">:</span> <span class="token string">'mini-program'</span></span>
