<span class="line">      <span class="token function-variable function">userPermissionsProvider</span><span class="token operator">:</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=></span> userPermissions<span class="token punctuation">,</span></span>
