<span class="line">  </span>
<span class="line">  appLog<span class="token punctuation">.</span><span class="token function">info</span><span class="token punctuation">(</span><span class="token string">'Application kit prepared successfully'</span><span class="token punctuation">,</span> <span class="token punctuation">{</span></span>
