<span class="line">    <span class="token punctuation">{</span> path<span class="token operator">:</span> <span class="token string">'/pages/checkout/index'</span><span class="token punctuation">,</span> name<span class="token operator">:</span> <span class="token string">'checkout'</span><span class="token punctuation">,</span> component<span class="token operator">:</span> <span class="token string">'pages/Checkout'</span> <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">{</span> path<span class="token operator">:</span> <span class="token string">'/pages/profile/index'</span><span class="token punctuation">,</span> name<span class="token operator">:</span> <span class="token string">'profile'</span><span class="token punctuation">,</span> component<span class="token operator">:</span> <span class="token string">'pages/Profile'</span> <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
