<span class="line">    <span class="token punctuation">{</span> path<span class="token operator">:</span> <span class="token string">'/pages/register/index'</span><span class="token punctuation">,</span> name<span class="token operator">:</span> <span class="token string">'register'</span><span class="token punctuation">,</span> component<span class="token operator">:</span> <span class="token string">'pages/Register'</span> <span class="token punctuation">}</span></span>
