<span class="line"><span class="token comment">// 5. 初始化应用</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">async</span> <span class="token keyword">function</span> <span class="token function">initializeApp</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  appLog<span class="token punctuation">.</span><span class="token function">info</span><span class="token punctuation">(</span><span class="token string">'Initializing Shop Application'</span><span class="token punctuation">,</span> <span class="token punctuation">{</span></span>
<span class="line">    version<span class="token operator">:</span> <span class="token string">'1.0.0'</span><span class="token punctuation">,</span></span>
<span class="line">    environment<span class="token operator">:</span> process<span class="token punctuation">.</span>env<span class="token punctuation">.</span><span class="token constant">NODE_ENV</span><span class="token punctuation">,</span></span>
<span class="line">    timestamp<span class="token operator">:</span> <span class="token keyword">new</span> <span class="token class-name">Date</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">toISOString</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  </span>
<span class="line">  <span class="token keyword">try</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">const</span> kit <span class="token operator">=</span> <span class="token keyword">await</span> <span class="token function">createKit</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">const</span> runtime <span class="token operator">=</span> <span class="token keyword">await</span> <span class="token function">createRuntime</span><span class="token punctuation">(</span>kit<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    </span>
<span class="line">    appLog<span class="token punctuation">.</span><span class="token function">info</span><span class="token punctuation">(</span><span class="token string">'Application initialized successfully'</span><span class="token punctuation">,</span> <span class="token punctuation">{</span></span>
<span class="line">      hasRequest<span class="token operator">:</span> <span class="token operator">!</span><span class="token operator">!</span>runtime<span class="token punctuation">.</span>request<span class="token punctuation">,</span></span>
<span class="line">      hasRouter<span class="token operator">:</span> <span class="token operator">!</span><span class="token operator">!</span>runtime<span class="token punctuation">.</span>router<span class="token punctuation">,</span></span>
<span class="line">      hasLogger<span class="token operator">:</span> <span class="token operator">!</span><span class="token operator">!</span>runtime<span class="token punctuation">.</span>logger<span class="token punctuation">,</span></span>
<span class="line">      timestamp<span class="token operator">:</span> <span class="token keyword">new</span> <span class="token class-name">Date</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">toISOString</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    </span>
<span class="line">    <span class="token comment">// 将运行时实例保存到全局</span></span>
<span class="line">    <span class="token punctuation">(</span>globalThis <span class="token keyword">as</span> <span class="token builtin">any</span><span class="token punctuation">)</span><span class="token punctuation">.</span>__SHOP_RUNTIME__ <span class="token operator">=</span> runtime<span class="token punctuation">;</span></span>
<span class="line">    </span>
<span class="line">    <span class="token comment">// 设置全局错误处理</span></span>
<span class="line">    <span class="token function">setupGlobalErrorHandling</span><span class="token punctuation">(</span>runtime<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    </span>
