<span class="line"></span>
<span class="line"><span class="token comment">// 应用初始化完成后设置路由守卫</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">function</span> <span class="token function">setupRouteGuards</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">const</span> <span class="token punctuation">{</span> router <span class="token punctuation">}</span> <span class="token operator">=</span> <span class="token punctuation">(</span>globalThis <span class="token keyword">as</span> <span class="token builtin">any</span><span class="token punctuation">)</span><span class="token punctuation">.</span>__SHOP_RUNTIME__<span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">const</span> log <span class="token operator">=</span> <span class="token function">getLog</span><span class="token punctuation">(</span><span class="token string">'RouteGuards'</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  </span>
