<span class="line">  router<span class="token punctuation">.</span><span class="token function">beforeEach</span><span class="token punctuation">(</span><span class="token keyword">async</span> <span class="token punctuation">(</span>to<span class="token punctuation">,</span> from<span class="token punctuation">)</span> <span class="token operator">=></span> <span class="token punctuation">{</span></span>
<span class="line">    log<span class="token punctuation">.</span><span class="token function">info</span><span class="token punctuation">(</span><span class="token string">'Route guard checking'</span><span class="token punctuation">,</span> <span class="token punctuation">{</span></span>
<span class="line">      from<span class="token operator">:</span> from<span class="token punctuation">.</span>path<span class="token punctuation">,</span></span>
<span class="line">      to<span class="token operator">:</span> to<span class="token punctuation">.</span>path<span class="token punctuation">,</span></span>
<span class="line">      timestamp<span class="token operator">:</span> <span class="token keyword">new</span> <span class="token class-name">Date</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">toISOString</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    </span>
<span class="line">    <span class="token comment">// 检查目标页面是否需要认证</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>to<span class="token punctuation">.</span>meta<span class="token operator">?.</span>requiresAuth<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">      <span class="token keyword">const</span> authStore <span class="token operator">=</span> <span class="token function">useAuthStore</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">      </span>
<span class="line">      <span class="token comment">// 如果尚未检查认证状态，先检查</span></span>
<span class="line">      <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>authStore<span class="token punctuation">.</span>isAuthenticated <span class="token operator">&amp;&amp;</span> <span class="token operator">!</span>authStore<span class="token punctuation">.</span>isCheckingAuth<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">await</span> authStore<span class="token punctuation">.</span><span class="token function">checkAuthStatus</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">      <span class="token punctuation">}</span></span>
<span class="line">      </span>
<span class="line">      <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>authStore<span class="token punctuation">.</span>isAuthenticated<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        log<span class="token punctuation">.</span><span class="token function">warn</span><span class="token punctuation">(</span><span class="token string">'Access denied - authentication required'</span><span class="token punctuation">,</span> <span class="token punctuation">{</span></span>
<span class="line">          attemptedRoute<span class="token operator">:</span> to<span class="token punctuation">.</span>path<span class="token punctuation">,</span></span>
<span class="line">          userId<span class="token operator">:</span> authStore<span class="token punctuation">.</span>user<span class="token operator">?.</span>id <span class="token operator">||</span> <span class="token string">'anonymous'</span></span>
<span class="line">        <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
